/* global __firebase_config, __app_id, __initial_auth_token */
import React, { useState, useEffect } from 'react';
import { 
  BrainCircuit, LogOut, Shield, User, GraduationCap, ArrowRight,
  Settings, ShieldCheck, Map, Wallet, BookOpen, Globe, Award, 
  Save, Clock, Phone, ChevronRight, MessageSquare, Bell, Calendar,
  Search, Send, LayoutDashboard, AlertCircle, Loader2
} from 'lucide-react';

// Firebase Imports
import { initializeApp } from 'firebase/app';
import { getAuth, signInAnonymously, signInWithCustomToken, onAuthStateChanged } from 'firebase/auth';
import { getFirestore, doc, setDoc, onSnapshot } from 'firebase/firestore';

// Your Specific Firebase Configuration (Fallback)
const myFirebaseConfig = {
  apiKey: "AIzaSyDutEHTfbkM9kDayAtCx3R9ZHIyxpuQJMA",
  authDomain: "studentsuccessai-611f1.firebaseapp.com",
  projectId: "studentsuccessai-611f1",
  storageBucket: "studentsuccessai-611f1.firebasestorage.app",
  messagingSenderId: "406714339262",
  appId: "1:406714339262:web:e439a293efcc7de2a8b3ef"
};

// Safely access global variables provided by the environment
const firebaseConfig = (typeof __firebase_config !== 'undefined' && __firebase_config) 
  ? JSON.parse(__firebase_config) 
  : myFirebaseConfig;

const app = initializeApp(firebaseConfig);
const auth = getAuth(app);
const db = getFirestore(app);

const appId = (typeof __app_id !== 'undefined' && __app_id) 
  ? __app_id 
  : 'studentsuccessai-611f1';

// URL for your FastAPI Backend
const API_URL = "http://127.0.0.1:8000";

// --- SUB-COMPONENT: STUDENT DASHBOARD ---
const StudentDashboard = ({ user }) => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [loadingAi, setLoadingAi] = useState(false);
  const [aiResult, setAiResult] = useState(null);
  const [error, setError] = useState(null);
  
  const [profile, setProfile] = useState({
    firstName: "Juan",
    lastName: "Dela Cruz",
    income: 8000,
    absences: 12,
    parentEdu: 2,         // (0-4)
    internetAccess: 0,    // (0 or 1)
    studyTime: 5,         // hours
    distanceToSchool: 15, // km
    bio: "Sophomore student."
  });

  // 1. Sync Profile from Firebase
  useEffect(() => {
    if (!user) return;
    const profileDocRef = doc(db, 'artifacts', appId, 'users', user.uid, 'settings', 'profile');
    const unsubscribe = onSnapshot(profileDocRef, (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        setProfile(data);
        // Automatically trigger AI analysis when data changes
        getAiPrediction(data);
      }
    }, (err) => console.error("Firestore error:", err));
    return () => unsubscribe();
  }, [user]);

  // 2. Updated Function to talk to the Python AI Backend
  const getAiPrediction = async (studentData) => {
    setLoadingAi(true);
    setError(null);
    try {
      const formData = new FormData();
      const headers = "name,income,absences,parent_edu,internet_access,study_time,distance_to_school";
      const values = `${studentData.firstName},${studentData.income},${studentData.absences},${studentData.parentEdu || 0},${studentData.internetAccess || 0},${studentData.studyTime || 0},${studentData.distanceToSchool || 0}`;
      
      const csvContent = `${headers}\n${values}`;
      const blob = new Blob([csvContent], { type: 'text/csv' });
      formData.append('file', blob, 'student.csv');

      const response = await fetch(`${API_URL}/analyze`, {
        method: 'POST',
        body: formData,
      });

      if (response.ok) {
        const data = await response.json();
        setAiResult(data[0]);
      } else {
        const errData = await response.json();
        setError(errData.detail || "Server Error");
      }
    } catch (err) {
      console.error("AI Server Unreachable:", err);
      setError("AI Engine Offline. Please check if backend is running.");
    } finally {
      setLoadingAi(false);
    }
  };

  const handleSaveProfile = async (e) => {
    e.preventDefault();
    if (!user) return;
    try {
      const profileDocRef = doc(db, 'artifacts', appId, 'users', user.uid, 'settings', 'profile');
      await setDoc(profileDocRef, profile);
    } catch (err) {
      console.error("Save failed:", err);
    }
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 items-start">
      <div className="w-full lg:w-64 shrink-0 bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-2">
        {[
          { id: 'dashboard', label: 'Dashboard', icon: <LayoutDashboard size={20} /> },
          { id: 'profile', label: 'Socioeconomic Data', icon: <User size={20} /> },
        ].map(item => (
          <button
            key={item.id}
            onClick={() => setActiveTab(item.id)}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl font-bold text-sm transition-all ${
              activeTab === item.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' : 'text-slate-400 hover:bg-slate-50'
            }`}
          >
            {item.icon} {item.label}
          </button>
        ))}
      </div>

      <div className="flex-1 w-full">
        {activeTab === 'dashboard' && (
          <div className="space-y-6">
            {error && (
              <div className="bg-amber-50 border border-amber-200 p-4 rounded-2xl flex items-center gap-3 text-amber-700 text-sm font-bold">
                <AlertCircle size={18} /> {error}
              </div>
            )}
            
            <div className={`bg-gradient-to-br ${aiResult?.at_risk ? 'from-rose-600 to-rose-800' : 'from-indigo-600 to-indigo-800'} p-8 rounded-[2.5rem] text-white shadow-xl transition-all`}>
               <div className="flex justify-between items-start">
                  <div>
                    <h2 className="text-2xl font-black mb-1">
                      {loadingAi ? "AI is Analyzing..." : (aiResult?.at_risk ? "Intervention Required" : "Academic Standing: Stable")}
                    </h2>
                    <p className="text-indigo-100 text-sm max-w-md">
                      {aiResult ? aiResult.solution : "Please update your profile to generate an AI success roadmap."}
                    </p>
                  </div>
                  {loadingAi ? <Loader2 className="animate-spin opacity-50" size={40} /> : <ShieldCheck size={48} className="opacity-40" />}
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Calculated Risk Score</p>
                  <p className={`text-4xl font-black ${aiResult?.at_risk ? 'text-rose-500' : 'text-indigo-600'}`}>
                    {aiResult ? `${aiResult.risk_score}%` : "--"}
                  </p>
                  <p className="text-xs text-slate-500 mt-2 font-medium">Derived from 7 socioeconomic indicators.</p>
               </div>
               <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">System Status</p>
                  <div className="flex items-center gap-2 mt-2">
                    <div className={`w-3 h-3 rounded-full ${aiResult ? 'bg-emerald-500' : 'bg-slate-300 animate-pulse'}`}></div>
                    <p className="text-sm font-bold text-slate-700">{aiResult ? "AI Online" : "Waiting for Data"}</p>
                  </div>
               </div>
            </div>
          </div>
        )}

        {activeTab === 'profile' && (
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-xl max-w-2xl">
            <h2 className="text-xl font-black mb-6">Socioeconomic Profile</h2>
            <form onSubmit={handleSaveProfile} className="space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2">Monthly Family Income (PHP)</label>
                  <input type="number" className="w-full p-4 bg-slate-50 rounded-2xl border border-slate-100 font-bold" 
                    value={profile.income} onChange={e => setProfile({...profile, income: parseInt(e.target.value) || 0})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2">Total Absences</label>
                  <input type="number" className="w-full p-4 bg-slate-50 rounded-2xl border border-slate-100 font-bold" 
                    value={profile.absences} onChange={e => setProfile({...profile, absences: parseInt(e.target.value) || 0})} />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2">Internet Access (1=Yes, 0=No)</label>
                  <input type="number" max="1" min="0" className="w-full p-4 bg-slate-50 rounded-2xl border border-slate-100 font-bold" 
                    value={profile.internetAccess} onChange={e => setProfile({...profile, internetAccess: parseInt(e.target.value) || 0})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2">Study Time (Hrs/Week)</label>
                  <input type="number" className="w-full p-4 bg-slate-50 rounded-2xl border border-slate-100 font-bold" 
                    value={profile.studyTime} onChange={e => setProfile({...profile, studyTime: parseInt(e.target.value) || 0})} />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2">Parent Edu Level (0-4)</label>
                  <input type="number" max="4" min="0" className="w-full p-4 bg-slate-50 rounded-2xl border border-slate-100 font-bold" 
                    value={profile.parentEdu} onChange={e => setProfile({...profile, parentEdu: parseInt(e.target.value) || 0})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2">Distance to School (KM)</label>
                  <input type="number" className="w-full p-4 bg-slate-50 rounded-2xl border border-slate-100 font-bold" 
                    value={profile.distanceToSchool} onChange={e => setProfile({...profile, distanceToSchool: parseFloat(e.target.value) || 0})} />
                </div>
              </div>

              <button type="submit" className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-indigo-600 transition-all">
                <Save size={18} /> Save & Run AI Analysis
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

export default function App() {
  const [sessionUser, setSessionUser] = useState(null);
  const [appRole, setAppRole] = useState(null);

  useEffect(() => {
    const initAuth = async () => {
      try {
        // Safe check for the global auth token
        const token = (typeof __initial_auth_token !== 'undefined') ? __initial_auth_token : null;
        
        if (token) {
          await signInWithCustomToken(auth, token);
        } else {
          await signInAnonymously(auth);
        }
      } catch (err) { 
        console.error("Auth failed:", err); 
      }
    };
    initAuth();
    const unsubscribe = onAuthStateChanged(auth, setUser => setSessionUser(setUser));
    return () => unsubscribe();
  }, []);

  if (!appRole) {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6 text-white">
        <div className="bg-[#0f172a] p-12 rounded-[3.5rem] border border-slate-800 w-full max-w-md text-center">
          <BrainCircuit className="text-indigo-400 w-12 h-12 mx-auto mb-8" />
          <h1 className="text-3xl font-black mb-10">SUCCESS<span className="text-indigo-500">PREDICT</span></h1>
          <div className="space-y-3">
            {['admin', 'teacher', 'student'].map(role => (
              <button key={role} onClick={() => setAppRole(role)} className="w-full py-5 bg-slate-800 hover:bg-indigo-600 rounded-[1.5rem] font-bold capitalize">
                {role} Portal
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc]">
      <nav className="bg-white border-b px-8 py-4 flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-2 font-black text-2xl tracking-tighter">
          <div className="bg-indigo-600 p-2 rounded-xl text-white"><BrainCircuit size={20}/></div>
          SUCCESS<span className="text-indigo-600">PREDICT</span>
        </div>
        <button onClick={() => setAppRole(null)} className="bg-red-50 text-red-500 p-3 rounded-2xl"><LogOut size={20} /></button>
      </nav>
      <main className="max-w-7xl mx-auto p-8">
        {appRole === 'student' && <StudentDashboard user={sessionUser} />}
        {appRole !== 'student' && <div className="p-12 text-center font-bold">Dashboard for {appRole} is under construction.</div>}
      </main>
    </div>
  );
}
